"""Пошаговые разборы главы 2.3: core_cpu.c для Windows, macOS и Linux, cpu_top.c и новые части brain.py.

Номера строк — по файлам tools/src23 (у brain.py — по фрагменту BRAIN_PART из ch23). Оформление — trace_html из walk11."""
from walk11 import like, trace_html


def build(hl, hl_py, src, brain_part):
    W = {}

    W['win'] = trace_html('core_cpu.c', 'win',
        'прочитать процессорное время процесса по его номеру и вернуть его в микросекундах: отдельно время программы и время ядра системы.',
        [('1-2', 'Подключить заголовочные файлы',
          '<p><code>windows.h</code> — функции и типы WinAPI, <code>core.h</code> — <code>struct core_cpu</code> и объявление функции.</p>'),
         ('4-9', 'Перевести FILETIME в микросекунды',
          '<p>Windows отдаёт время в структуре <code>FILETIME</code>: это 64-битное число отрезков по 100 наносекунд, разрезанное на две 32-битные половины, <code>dwLowDateTime</code> и <code>dwHighDateTime</code>. <code>ULARGE_INTEGER</code> складывает половины обратно в одно число <code>QuadPart</code>. В одной микросекунде 10 отрезков по 100 нс, поэтому число делится на 10.</p>'
          + like('Счётчик в десятых долях копейки: чтобы получить копейки, делят на 10.')),
         ('11-15', 'Начать функцию и проверить параметры',
          '<p>Четыре <code>FILETIME</code>: когда процесс создан, когда завершился, сколько времени выполнялся в ядре системы и сколько — в своём коде. Без места для ответа или с отрицательным номером — код 87, <code>ERROR_INVALID_PARAMETER</code>.</p>'),
         ('16-18', 'Открыть процесс',
          '<p><code>OpenProcess</code> даёт дескриптор процесса по номеру. Первый параметр — какие права нужны. <code>PROCESS_QUERY_LIMITED_INFORMATION</code> — самое узкое право «прочитать сведения»: его Windows даёт к большинству процессов пользователя. <code>FALSE</code> — дочерние процессы дескриптор не наследуют.</p>'
          '<p>Если процесса нет, функция возвращает <code>NULL</code>, а <code>GetLastError</code> — 87. Если прав не хватает, например у процесса System с номером 4, — 5, <code>ERROR_ACCESS_DENIED</code>.</p>'),
         ('19-24', 'Прочитать времена и закрыть дескриптор',
          '<p><code>GetProcessTimes</code> заполняет все четыре <code>FILETIME</code>. Код ошибки берётся до <code>CloseHandle</code>: сама <code>CloseHandle</code> может записать в последнюю ошибку потока своё значение. Дескриптор закрывается на обоих путях — и при ошибке, и при успехе, иначе каждый вызов оставлял бы открытый дескриптор, как в главе 2.2.</p>'),
         ('25-27', 'Записать ответ',
          '<p>Время в ядре системы и время в своём коде переводятся в микросекунды и кладутся в структуру. Время создания и завершения функции не нужно.</p>')],
        [('pid', 'номер'), ('OpenProcess', 'дескриптор'), ('GetProcessTimes', 'FILETIME по 100 нс'), ('/ 10', 'микросекунды')],
        hl(src('win')))

    W['mac'] = trace_html('core_cpu.c', 'mac',
        'прочитать процессорное время процесса по его номеру и вернуть его в микросекундах: отдельно время программы и время ядра системы.',
        [('1-4', 'Подключить заголовочные файлы',
          '<ul class="words"><li><code>errno.h</code> — коды ошибок;</li>'
          '<li><code>libproc.h</code> — <code>proc_pidinfo</code>, та же библиотека, что дала список процессов в главе 2.1;</li>'
          '<li><code>mach/mach_time.h</code> — <code>mach_timebase_info</code>, перевод тиков в наносекунды.</li></ul>'),
         ('6-11', 'Начать функцию и проверить параметры',
          '<p><code>struct proc_taskinfo ti</code> — сюда система запишет сведения о процессе: память, число потоков и процессорное время. <code>tb</code> — множитель для перевода тиков. Без места для ответа или с отрицательным номером — код 22, <code>EINVAL</code>.</p>'),
         ('12-16', 'Прочитать сведения о процессе',
          '<p><code>proc_pidinfo</code> с видом <code>PROC_PIDTASKINFO</code> заполняет <code>ti</code> и возвращает, сколько байт записала. 0 или меньше — ошибка, её код в <code>errno</code>: 3 — <code>ESRCH</code>, процесса нет; 1 — <code>EPERM</code>, процесс чужой, например процесс 1 <code>launchd</code> от имени системы. Если записано меньше, чем размер структуры, ответ неполный, и функция тоже сообщает, что процесса нет.</p>'),
         ('17-19', 'Перевести тики в микросекунды',
          '<p>Поля <code>pti_total_user</code> и <code>pti_total_system</code> считают время в тиках Mach — единицах счётчика времени процессора. <code>mach_timebase_info</code> даёт дробь <code>numer / denom</code>: сколько наносекунд в одном тике. На компьютерах Mac с процессором Intel дробь равна 1/1, на процессорах Apple — 125/3, один тик — около 41,7 нс. Тики умножаются на дробь, получаются наносекунды, деление на 1000 даёт микросекунды.</p>'
          '<p>Умножение стоит раньше деления: при обратном порядке <code>tb.numer / tb.denom</code> в целых числах дало бы 41 вместо 41,67.</p>'),
         ('20', 'Вернуть успех', '<p>0 — время записано в <code>out</code>.</p>')],
        [('pid', 'номер'), ('proc_pidinfo', 'тики Mach'), ('× numer / denom', 'наносекунды'), ('/ 1000', 'микросекунды')],
        hl(src('mac')))

    W['linux'] = trace_html('core_cpu.c', 'linux',
        'прочитать процессорное время процесса по его номеру и вернуть его в микросекундах: отдельно время программы и время ядра системы.',
        [('1-5', 'Подключить заголовочные файлы',
          '<p><code>stdio.h</code> — <code>fopen</code>, <code>fread</code> и <code>sscanf</code>, <code>string.h</code> — <code>strrchr</code>, <code>unistd.h</code> — <code>sysconf</code>.</p>'),
         ('7-12', 'Начать функцию и проверить параметры',
          '<p><code>path</code> — путь к файлу, <code>line</code> — его содержимое. Файл <code>/proc/PID/stat</code> — одна строка, обычно около 300 символов, 512 хватает. Без места для ответа или с отрицательным номером — код 22, <code>EINVAL</code>.</p>'),
         ('13-19', 'Прочитать /proc/PID/stat',
          '<p>Linux показывает сведения о каждом процессе файлами в папке <code>/proc</code>, как в главе 2.1. <code>snprintf</code> собирает путь, например <code>/proc/321/stat</code>. Если процесса нет, нет и папки: <code>fopen</code> возвращает <code>NULL</code>, а <code>errno</code> — 2, <code>ENOENT</code>. <code>fread</code> читает строку целиком, нулевой байт в конце делает из неё строку C.</p>'),
         ('21-23', 'Найти конец имени',
          '<p>Строка начинается так: <code>321 (python3) R 320 …</code> — номер, имя в скобках, состояние и дальше числа через пробел. Имя программы может содержать пробелы и даже скобки, поэтому <code>strrchr</code> ищет <i>последнюю</i> закрывающую скобку. После неё всё — числа без сюрпризов.</p>'),
         ('24-25', 'Взять поля 14 и 15',
          '<p><code>close + 2</code> — первый символ после скобки и пробела, поле 3, состояние. <code>%*c</code> и <code>%*d</code> читают поле и выбрасывают его: звёздочка значит «не сохранять». После состояния пропускаются ещё десять полей, с 4-го по 13-е. Два <code>%llu</code> забирают поле 14 — <code>utime</code>, время в своём коде, и поле 15 — <code>stime</code>, время в ядре системы. <code>sscanf</code> возвращает, сколько значений сохранено; не 2 — строка другого вида.</p>'),
         ('26-28', 'Перевести тики в микросекунды',
          '<p>Поля 14 и 15 считают время в тиках часов ядра. <code>sysconf(_SC_CLK_TCK)</code> — сколько тиков в секунде, в Linux почти всегда 100: один тик — 10 мс. Тики умножаются на миллион и делятся на число тиков в секунде.</p>'),
         ('29', 'Вернуть успех', '<p>0 — время записано в <code>out</code>.</p>')],
        [('pid', 'номер'), ('/proc/PID/stat', 'строка'), ('поля 14 и 15', 'тики по 10 мс'), ('× 1 000 000 / hz', 'микросекунды')],
        hl(src('linux')))

    W['top'] = trace_html('cpu_top.c', 'win mac linux',
        'проверить ядро без Python: запустить процесс-нагрузку, замерить его процессорное время дважды с паузой в секунду и посчитать загрузку. С номером процесса в командной строке — один замер этого процесса.',
        [('1-4', 'Подключить заголовочные файлы',
          '<p><code>inttypes.h</code> — формат <code>PRId64</code>, <code>stdlib.h</code> — <code>atoll</code> и <code>exit</code>.</p>'),
         ('6-17', 'Пауза и имя Python для своей системы',
          '<p><code>#ifdef _WIN32</code> выбирает кусок кода при сборке: компилятор Windows задаёт имя <code>_WIN32</code>. В Windows пауза — <code>Sleep</code> в миллисекундах, Python запускается командой <code>python</code>. В macOS и Linux пауза — <code>nanosleep</code>: структура <code>timespec</code> из секунд и наносекунд, 1300 мс — это 1 секунда и 300 000 000 нс. Python там называется <code>python3</code>.</p>'),
         ('19-28', 'Один замер',
          '<p><code>used</code> вызывает <code>core_proc_cpu</code>, печатает оба времени и возвращает их сумму. При ошибке печатает код и завершает программу с кодом 1.</p>'),
         ('30-34', 'Режим «номер в командной строке»',
          '<p><code>cpu_top 4</code> — один замер процесса 4. <code>atoll</code> переводит строку в число <code>long long</code>.</p>'),
         ('35-42', 'Запустить нагрузку',
          '<p>Нагрузка — Python с пустым циклом на 2 секунды, как в ЛР 6. <code>\\n</code> внутри строки — перевод строки: программа для <code>-c</code> из трёх строк. Запускает её <code>core_spawn</code> из главы 2.2.</p>'),
         ('43-46', 'Два замера',
          '<p>Первые 300 мс Python загружается, поэтому первый замер — через 300 мс, второй — ещё через секунду.</p>'),
         ('47-48', 'Посчитать загрузку',
          '<p><code>core_wait</code> забирает код нагрузки, чтобы не оставить зомби. Прирост <code>b - a</code> — сколько микросекунд процессорного времени нагрузка получила за секунду. Деление на 10 000 даёт проценты: 1 000 000 мкс — 100%.</p>')],
        [('core_spawn', 'нагрузка'), ('used', 'замер 1'), ('1 с', 'пауза'), ('used', 'замер 2'), ('b − a', 'загрузка')],
        hl(src('top')))

    W['brain'] = trace_html('brain.py · новые части', 'win mac linux',
        'дать мозгу две функции: <code>proc_cpu</code> читает процессорное время одного процесса, <code>cpu_load</code> считает загрузку всех процессов за интервал и сортирует их.',
        [('1-5', 'Описать struct core_cpu',
          '<p>Два поля по 8 байт, как в <code>core.h</code>.</p>'),
         ('7-8', 'Описать функцию ядра',
          '<p>Номер процесса — <code>c_int64</code>, ответ — адрес структуры <code>CoreCpu</code>.</p>'),
         ('10-14', 'proc_cpu: время одного процесса',
          '<p>Возвращает сумму времени программы и времени ядра в микросекундах. Если процесс не читается — завершился или чужой, — функция возвращает <code>None</code> без исключения: в списке из сотен процессов такие есть всегда, и мозг их пропускает.</p>'),
         ('16-22', 'cpu_load: два снимка',
          '<p>Список процессов берётся один раз. <code>before</code> — словарь «номер → время» до паузы, <code>after</code> — после. <code>time.monotonic()</code> — часы, которые идут только вперёд: перевод системных часов их не сдвигает. По ним считается настоящая длина паузы <code>wall_us</code>: обход сотен процессов тоже занимает время, и пауза выходит чуть длиннее <code>interval</code>.</p>'
          + like('Показания всех счётчиков воды в доме записывают утром и вечером, а расход считают по разнице.')),
         ('23-28', 'Посчитать загрузку и отсортировать',
          '<p>Процесс, который не прочитался хотя бы в одном снимке, пропускается. Для остальных прирост времени делится на длину паузы и умножается на 100. <code>sorted(…, reverse=True)</code> ставит самые занятые процессы первыми.</p>')],
        [('list_procs', 'номера'), ('proc_cpu × 2', 'два снимка'), ('(b − a) / wall', 'проценты'), ('sorted', 'самые занятые')],
        hl_py(brain_part))
    return W
